<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {batchCheckReasons,parseBatchCheck,type Batch,type BatchCheck} from './sync-batch';
const props=defineProps<{batch:Batch;disabled:boolean;syncActive:boolean}>(),emit=defineEmits<{authenticationRequired:[];observed:[check:BatchCheck|null]}>();
const result=ref<BatchCheck|null>(null),history=ref<BatchCheck[]>([]),busy=ref(false),error=ref(''),offset=ref(0),more=ref(false);
const labels:Record<string,string>={incomplete:'尚无完成凭据',verified:'本次核对全部通过',rejected:'本次核对拒绝',failed:'本次核对失败',not_checked:'未核对'};
let active=true,generation=0,controller:AbortController|undefined;
const current=(n:number)=>active&&n===generation;
function invalidate(){generation++;controller?.abort();busy.value=false}
async function request(url:string,body?:unknown){const n=generation;const r=await fetch(url,{method:body===undefined?'GET':'POST',credentials:'same-origin',signal:controller?.signal,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!current(n))throw new DOMException('旧请求','AbortError');if(r.status===401){stop();emit('authenticationRequired');throw Error('登录已失效')}if(!r.ok)throw Error((await r.text()).slice(0,1000)||'批次核对暂不可读');const data=await r.json();if(!current(n))throw new DOMException('旧请求','AbortError');return data}
async function check(){if(!active||busy.value||props.disabled||props.syncActive)return;const n=++generation;controller=new AbortController();busy.value=true;try{const data=await request('/api/sync/resolution-batches/'+props.batch.id+'/checks',{});if(!current(n))return;result.value=parseBatchCheck(data,props.batch,true);error.value=''}catch(e){if(current(n))error.value=(e instanceof Error?e.message:String(e))+'；请读取核对历史查找记录，不会自动重提。'}finally{if(current(n))busy.value=false}}
async function list(at=0){if(!active||busy.value||props.disabled)return;const n=++generation;controller=new AbortController();busy.value=true;try{const data=await request('/api/sync/resolution-batches/'+props.batch.id+'/checks?offset='+at);if(!current(n))return;if(data.batch_id!==props.batch.id||data.offset!==at||typeof data.has_more!=='boolean'||!Array.isArray(data.checks)||data.checks.length>25||data.has_more&&data.checks.length!==25)throw Error('核对历史范围无效');const rows=data.checks.map((r:any)=>parseBatchCheck(r,props.batch));if(new Set(rows.map((r:BatchCheck)=>r.id)).size!==rows.length)throw Error('核对历史身份重复');history.value=rows;offset.value=at;more.value=data.has_more;error.value=''}catch(e){if(current(n))error.value=e instanceof Error?e.message:String(e)}finally{if(current(n))busy.value=false}}
async function read(record:BatchCheck){if(!active||busy.value||props.disabled)return;const n=++generation;controller=new AbortController();busy.value=true;try{const data=await request('/api/sync/resolution-batch-checks/'+record.id);if(!current(n))return;const parsed=parseBatchCheck(data,props.batch,true);if(parsed.id!==record.id)throw Error('核对详情身份不符');result.value=parsed;error.value=''}catch(e){if(current(n))error.value=e instanceof Error?e.message:String(e)}finally{if(current(n))busy.value=false}}
watch(result,value=>emit('observed',value));
function reset(){invalidate();result.value=null;history.value=[];offset.value=0;more.value=false;error.value=''}
function stop(){active=false;invalidate()}
function restore(){active=true}
watch(()=>props.batch.id,reset);watch(()=>props.disabled,v=>{if(v)invalidate()});
onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore)});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore)});
</script>
<template><section class="batch-check-panel" data-testid="batch-check-panel"><header><h3>核对所选全部项目</h3><button class="button secondary compact" data-testid="batch-check-start" :disabled="busy||disabled||syncActive" @click="check">重新核对整批</button></header><p class="muted">一次完整观察核对全部固定条目，包含网盘内容下载校验，可能需要等待。核对本身不执行文件操作，也不会自动开始执行。</p><p v-if="busy" role="status">正在读取或核对…</p><p v-if="error" role="alert" class="notice danger">{{error}}<span v-if="result"> · 保留上次读取的核对结果。</span></p><section v-if="result" data-testid="batch-check-result"><strong>{{labels[result.status]}}</strong><p>{{batchCheckReasons[result.reason]}}</p><p class="muted">核对 {{result.id}}<br>开始 UTC {{result.started_at_utc}}<br>完成 UTC {{result.status==='incomplete'?'尚无完成凭据':result.finished_at_utc}}</p><div class="table-wrap"><table><thead><tr><th>顺序</th><th>项目</th><th>结果</th><th>原因 / 子树项目数</th></tr></thead><tbody><tr v-for="(item,i) in result.items" :key="item.decision_id"><td>{{i+1}}</td><td>{{batch.items[i]?.root}}</td><td>{{labels[item.status]}}</td><td>{{batchCheckReasons[item.reason]}}<small v-if="item.subtree">本地 {{item.subtree.local_expected_items}} → {{item.subtree.local_observed_items}} · 网盘 {{item.subtree.remote_expected_items}} → {{item.subtree.remote_observed_items}}</small></td></tr></tbody></table></div><a class="button secondary compact" :href="'/api/sync/resolution-batch-checks/'+result.id" target="_blank" rel="noopener">查看共同快照与完整核对证据</a></section><header><h4>已保存的核对</h4><button class="button secondary compact" data-testid="batch-check-history" :disabled="busy||disabled" @click="list()">读取核对历史</button></header><div v-if="history.length" class="table-wrap"><table><thead><tr><th>开始 UTC</th><th>完成 UTC</th><th>结果</th><th>查看</th></tr></thead><tbody><tr v-for="record in history" :key="record.id"><td>{{record.started_at_utc}}</td><td>{{record.status==='incomplete'?'未完成':record.finished_at_utc}}</td><td>{{labels[record.status]}}</td><td><button class="button secondary compact" :disabled="busy||disabled" @click="read(record)">读取完整记录</button></td></tr></tbody></table><footer><button class="button secondary compact" :disabled="busy||disabled||!offset" @click="list(Math.max(0,offset-25))">上一页核对</button><button class="button secondary compact" :disabled="busy||disabled||!more" @click="list(offset+25)">下一页核对</button></footer></div></section></template>
<style scoped>.batch-check-panel{border-top:1px solid #dce5ef;margin-top:18px;padding-top:12px}header,footer{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px;margin:10px 0}th,td{padding:8px 10px;border-bottom:1px solid #e4eaf2;vertical-align:top;overflow-wrap:anywhere}th{background:#f5f7fb;white-space:nowrap}small{display:block;color:#65748b;margin-top:4px}p{overflow-wrap:anywhere}</style>
